                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            result.append((color, cells))
    return result

def _l_orientation(cells):
    rs = [r for r, c in cells]
    cs = [c for r, c in cells]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    if r0 == r1 or c0 == c1 or len(cells) != (r1-r0+1) + (c1-c0+1) - 1:
        return None
    # Return the corner of the L: top-left, top-right, bottom-left, bottom-right.
    for corner, vr, hc in (
        ('tl', range(r0, r1+1), range(c0, c1+1)),
        ('tr', range(r0, r1+1), range(c1, c0-1, -1)),
        ('bl', range(r1, r0-1, -1), range(c0, c1+1)),
        ('br', range(r1, r0-1, -1), range(c1, c0-1, -1)),
    ):
        # Validate both arms originate at the designated corner.
        if corner == 'tl': arm = {(r,c0) for r in range(r0,r1+1)} | {(r0,c) for c in range(c0,c1+1)}
        elif corner == 'tr': arm = {(r,c1) for r in range(r0,r1+1)} | {(r0,c) for c in range(c0,c1+1)}
        elif corner == 'bl': arm = {(r,c0) for r in range(r0,r1+1)} | {(r1,c) for c in range(c0,c1+1)}
        else: arm = {(r,c1) for r in range(r0,r1+1)} | {(r1,c) for c in range(c0,c1+1)}
        if cells == arm:
            return corner
    return None

