                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            out.append((color, cells))
    return out

def _canonical(cells):
    forms = []
    for reflect in (1, -1):
        for rot in range(4):
            pts = []
            for r, c in cells:
                x, y = r, reflect * c
                for _ in range(rot):
                    x, y = y, -x
                pts.append((x, y))
            mr = min(x for x, y in pts)
            mc = min(y for x, y in pts)
            forms.append(tuple(sorted((x-mr, y-mc) for x, y in pts)))
    return min(forms)

def _is_l(cells):
    rs = [r for r, c in cells]
    cs = [c for r, c in cells]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    h, w = r1-r0+1, c1-c0+1
    if h <= 1 or w <= 1 or len(cells) != h+w-1:
        return False
    for rr, cc in ((r0,c0),(r0,c1),(r1,c0),(r1,c1)):
        arm = {(r,cc) for r in range(r0,r1+1)} | {(rr,c) for c in range(c0,c1+1)}
        if cells == arm:
            return True
    return False

