    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid, bg)
    keys = [(color, cells) for color, cells in comps if len(cells) >= 7 and _is_l(cells)]
    if not keys:
        return [row[:] for row in grid]
    key_color, key = max(keys, key=lambda item: len(item[1]))
