            continue
        for color, cells in objects:
            cr = sum(r for r, c in cells) / len(cells)
            cc = sum(c for r, c in cells) / len(cells)
            dist = (cr-kr)**2 + (cc-kc)**2
            candidates.append((dist, color, cells))
